INSERT INTO NMCP_RATE_RES_CHG_BAS@DL_MCP(
    RATE_RES_CHG_SEQ
  , SVC_CNTR_NO
  , MOBILE_NO
  , USER_ID
  , EVENT_CODE
  , RES_CHG_RATE_CD
  , BEF_CHG_RATE_CD
  , BEF_CHG_RATE_AMNT
  , PARAM
  , RES_CHG_DATE
  , RES_CHG_APY_DATE
  , TRT_MDL_DIV
  , GLOBAL_NO
  , BATCH_RSLT_CD
  , CRET_IP
  , CRET_DT
)VALUES(
   (SELECT NVL(MAX(RATE_RES_CHG_SEQ), 0) + 1 AS RATE_RES_CHG_SEQ  FROM NMCP_RATE_RES_CHG_BAS@DL_MCP)
 ,#{svcCntrNo}
 ,#{mobileNo}
 ,#{userid}
 ,#{eventCode}
 ,#{resChgRateCd}
 ,#{befChgRateCd}
 ,#{befChgRateAmnt}
 ,#{param}
 ,#{resChgDate}
 ,#{resChgApyDate}
 ,#{trtMdlDiv}
 ,#{globalNo}
 ,#{batchRsltCd}
 ,#{cretIp}
 ,SYSDATE
 )
